"use client";

import Link from "next/link";
import { ChevronRight, Hourglass, Sparkles, TriangleAlert } from "lucide-react";
import { useData } from "@/lib/data";
import { dayLabel, isSunday, monthLabel, monthOf } from "@/lib/dates";
import {
  capFor,
  currentBalance,
  dueIn,
  installmentsTotal,
  isMonthly,
  moodFor,
  projection,
  spentInMonth,
  weekStats,
} from "@/lib/finance";
import { rupees, rupeesShort } from "@/lib/format";
import { DueRow } from "@/components/DueRow";
import { ExpenseList } from "@/components/ExpenseList";
import { Mascot, moodLine } from "@/components/Mascot";
import { MonthlyAllowanceCard } from "@/components/MonthlyAllowanceCard";
import { PowerMeter } from "@/components/PowerMeter";
import { ThemeToggle } from "@/components/ThemeToggle";
import { useNow, useToday } from "@/components/UIProvider";
import { Bar, Empty, JpTag, Money, Panel, Stat, cx } from "@/components/ui";

export default function Home() {
  const { plan, expenses, commitments, wishlist, pots } = useData();
  const today = useToday();
  const now = useNow();
  const month = monthOf(today);
  const week = weekStats(plan, expenses, today);
  const mood = moodFor(week);
  const balance = currentBalance(plan, expenses, commitments, today);
  const proj = projection(plan, expenses, commitments, today);
  const cap = capFor(plan, month);
  const pocket = spentInMonth(expenses, month);
  const due = dueIn(commitments, month);
  const unpaid = due.filter((d) => !d.paid);
  const unpaidSum = unpaid.reduce((s, d) => s + d.c.amount, 0);
  const instTotal = installmentsTotal(commitments, month);
  const potSaved = pots.reduce((s, p) => s + p.saved, 0);
  const potTarget = pots.reduce((s, p) => s + p.target, 0);
  const waiting = wishlist.filter((w) => w.status === "waiting");
  const ready = waiting.filter((w) => now - w.createdAt >= plan.wishlistHours * 3600_000).length;
  const avoided = wishlist.filter((w) => w.status === "dropped").reduce((s, w) => s + w.amount, 0);
  const monthlyCats = plan.categories.filter(isMonthly);
  const perDay = week.daysLeft > 0 ? Math.max(0, week.left) / week.daysLeft : 0;
  const over = week.left < 0;
  const next = [...plan.milestones].sort((a, b) => a - b).find((m) => balance < m);

  const headsUp = [
    isSunday(today) && { href: "/checkin", icon: <Sparkles size={15} />, text: "Sunday check-in is ready", tone: "violet" },
    ready > 0 && {
      href: "/wishlist",
      icon: <Hourglass size={15} />,
      text: `${ready} wishlist item${ready > 1 ? "s" : ""} finished cooling off`,
      tone: "yellow",
    },
    instTotal > plan.installmentWarn && {
      href: "/installments",
      icon: <TriangleAlert size={15} />,
      text: `EMIs this month ${rupees(instTotal)}, over your ${rupeesShort(plan.installmentWarn)} limit`,
      tone: "red",
    },
  ].filter(Boolean) as { href: string; icon: React.ReactNode; text: string; tone: string }[];

  return (
    <div className="mx-auto w-full max-w-[1600px]">
      <header className="mb-4 flex items-center gap-2">
        <div>
          <p className="text-xs font-bold text-muted">
            {dayLabel(today)} · week {dayLabel(week.start)} – {dayLabel(week.end)}
          </p>
          <h1 className="display text-[1.7rem] leading-tight">
            Okaeri! <span className="jp text-base text-pink-ink">おかえり</span>
          </h1>
        </div>
        <ThemeToggle className="ml-auto md:hidden" />
      </header>

      <div className="grid gap-4 lg:grid-cols-12 lg:gap-5">
        {/* hero: the one number that matters */}
        <section className={cx("panel glow p-4 sm:p-5 lg:col-span-5", over && "bg-red/5")}>
          <div className="flex items-center gap-3">
            <Mascot mood={mood} size={104} className="shrink-0" />
            <div className="min-w-0 flex-1">
              <div className="relative mb-2 inline-block rounded-2xl bg-sunk px-3 py-1.5 text-xs font-bold">
                {moodLine[mood]}
              </div>
              <p className="label flex items-center gap-1.5">
                {over ? "Over budget this week" : "Left to spend this week"} <JpTag>残り</JpTag>
              </p>
              <Money
                value={over ? -week.left : week.left}
                className={cx("block text-[2.9rem] leading-[1.05] sm:text-[3.3rem]", over && "text-red-ink")}
              />
            </div>
          </div>
          <Bar className="mt-3" value={week.spent} max={week.budget} color={mood === "happy" ? "green" : mood === "worried" ? "yellow" : "red"} height={12} />
          <div className="mt-1.5 flex justify-between text-xs font-semibold text-muted">
            <span>
              Spent <Money value={week.spent} className="text-ink" /> of <Money value={week.budget} className="text-ink" />
            </span>
            <span>
              {week.daysLeft} day{week.daysLeft === 1 ? "" : "s"} left
              {!over && week.daysLeft > 0 && (
                <>
                  {" "}· <Money value={perDay} className="text-ink" />/day
                </>
              )}
            </span>
          </div>
        </section>

        {/* at-a-glance tiles */}
        <div className="grid grid-cols-2 gap-3 sm:gap-4 lg:col-span-7 lg:gap-5">
          <Stat label={`Pocket spend · ${monthLabel(month)}`} jp="生活費" sub={<>{rupees(Math.max(0, cap - pocket))} left of {rupees(cap)}</>}>
            <Money value={pocket} className={cx("text-[1.6rem] leading-none", pocket > cap && "text-red-ink")} />
            <Bar className="mt-2" value={pocket} max={cap} color="cyan" height={6} />
          </Stat>
          <Stat label="Savings now" jp="貯金" sub={next ? `${rupees(next - balance)} to ${rupeesShort(next)} ★` : "All milestones hit ★"}>
            <Money value={balance} className="text-[1.6rem] leading-none" />
            <Bar className="mt-2" value={balance} max={plan.goal} color="violet" height={6} />
          </Stat>
          <Stat
            label="Due this month"
            jp="支払い"
            sub={unpaid.length ? `${unpaid.length} payment${unpaid.length > 1 ? "s" : ""} not marked paid` : "All paid ✓"}
          >
            <Money value={unpaidSum} className={cx("text-[1.6rem] leading-none", unpaidSum > 0 && "text-pink-ink")} />
            <Bar className="mt-2" value={due.length - unpaid.length} max={Math.max(1, due.length)} color="green" height={6} />
          </Stat>
          <Stat label="Set aside" jp="積立" sub={pots.map((p) => `${p.name.split(" ")[0]} ${rupeesShort(p.saved)}`).join(" · ")}>
            <Money value={potSaved} className="text-[1.6rem] leading-none" />
            <Bar className="mt-2" value={potSaved} max={potTarget} color="yellow" height={6} />
          </Stat>
        </div>

        {headsUp.length > 0 && (
          <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap lg:col-span-12">
            {headsUp.map((h) => (
              <Link
                key={h.href}
                href={h.href}
                className="anim-pop flex items-center gap-2 rounded-full border px-3.5 py-2 text-sm font-bold"
                style={{
                  borderColor: `color-mix(in srgb, var(--${h.tone}) 40%, transparent)`,
                  background: `color-mix(in srgb, var(--${h.tone}) 12%, var(--panel))`,
                  color: `var(--${h.tone}-ink)`,
                }}
              >
                {h.icon}
                {h.text}
                <ChevronRight size={14} />
              </Link>
            ))}
          </div>
        )}

        <Panel title="This week by category" jp="分類" className="lg:col-span-4">
          <ul className="space-y-2.5">
            {week.perCat
              .filter((c) => c.budget > 0 || c.spent > 0)
              .map(({ cat, budget, spent }) => (
                <li key={cat.id}>
                  <div className="mb-1 flex items-baseline gap-2 text-sm">
                    <span>{cat.emoji}</span>
                    <span className="font-bold">{cat.name}</span>
                    <span className={cx("ml-auto text-xs font-semibold", spent > budget ? "text-red-ink" : "text-muted")}>
                      <Money value={spent} className="text-sm text-ink" /> / <Money value={budget} />
                    </span>
                  </div>
                  <Bar value={spent} max={budget} color={cat.color} height={8} />
                </li>
              ))}
          </ul>
        </Panel>

        <div className="grid gap-4 lg:col-span-4 lg:gap-5">
          {monthlyCats.map((cat) => (
            <MonthlyAllowanceCard key={cat.id} cat={cat} />
          ))}
          <Panel
            title="Wishlist"
            jp="欲しい"
            right={
              <Link href="/wishlist" className="text-xs font-bold text-pink-ink">
                Open
              </Link>
            }
          >
            <div className="flex items-center justify-between text-sm font-semibold">
              <span className="text-muted">
                {waiting.length ? `${waiting.length} cooling off (${rupees(waiting.reduce((s, w) => s + w.amount, 0))})` : "Nothing cooling off"}
              </span>
              <span>
                <Money value={avoided} className="text-green-ink" /> <span className="text-xs text-muted">avoided</span>
              </span>
            </div>
          </Panel>
        </div>

        <Panel
          title="Payments this month"
          jp="固定費"
          className="lg:col-span-4"
          right={
            <Link href="/month" className="text-xs font-bold text-pink-ink">
              Month view
            </Link>
          }
        >
          {due.length === 0 ? (
            <Empty>Nothing due this month.</Empty>
          ) : (
            <ul className="divide-y divide-line">
              {[...unpaid, ...due.filter((d) => d.paid)].map((d) => (
                <DueRow key={d.c.id} c={d.c} month={month} paid={d.paid} />
              ))}
            </ul>
          )}
        </Panel>

        <Panel
          title="Recent spends"
          jp="最近"
          className="lg:col-span-6 xl:col-span-7"
          right={
            <Link href="/month" className="text-xs font-bold text-pink-ink">
              All
            </Link>
          }
        >
          <ExpenseList items={expenses.filter((e) => e.date <= today).slice(0, 6)} empty="Tap + to log your first expense." />
        </Panel>

        <PowerMeter
          className="lg:col-span-6 xl:col-span-5"
          balance={balance}
          goal={plan.goal}
          milestones={plan.milestones}
          projected={proj[proj.length - 1]?.projected}
        />
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { TriangleAlert } from "lucide-react";
import { useData } from "@/lib/data";
import { dayLabel, monthLabel, monthOf } from "@/lib/dates";
import { budgetsFor, inflowsIn, isTripMonth, monthSummary, salaryShare, spentInMonth, takeHome } from "@/lib/finance";
import { rupees } from "@/lib/format";
import { DueRow } from "@/components/DueRow";
import { ExpenseList } from "@/components/ExpenseList";
import { MonthPicker, defaultMonth } from "@/components/MonthPicker";
import { useToday } from "@/components/UIProvider";
import { Bar, Empty, Money, PageTitle, Panel, cx } from "@/components/ui";

export default function MonthPage() {
  const { plan, expenses, commitments } = useData();
  const today = useToday();
  const [month, setMonth] = useState(() => defaultMonth(plan, today));
  const s = monthSummary(plan, expenses, commitments, month, today);
  const budgets = budgetsFor(plan, month);
  const fixed = s.due.filter((d) => d.c.mode !== "cash");
  const oneTime = s.due.filter((d) => d.c.mode === "cash");
  const fixedTotal = fixed.reduce((a, d) => a + d.c.amount, 0);
  const ins = inflowsIn(plan, month);
  const isCurrent = month === monthOf(today);
  const isPast = month < monthOf(today);
  const shownSaved = isPast ? s.savedSoFar : s.projectedSaved;
  const items = expenses.filter((e) => monthOf(e.date) === month);

  return (
    <div className="mx-auto w-full max-w-[1600px] space-y-4">
      <PageTitle
        title={monthLabel(month, "long")}
        jp="今月"
        sub={isTripMonth(plan, month) ? <span className="text-pink-ink">Trip month ✈︎</span> : undefined}
      />
      <MonthPicker plan={plan} value={month} onChange={setMonth} />

      <div className="page-grid">
      {/* savings vs target */}
      <Panel title="Savings" jp="貯金">
        <div className="grid grid-cols-2 gap-3">
          <Stat label={isPast ? "Saved" : isCurrent ? "On track to save" : "Planned to save"}>
            <Money value={shownSaved} className={cx("text-[1.9rem] leading-none", shownSaved < s.target && "text-red-ink")} />
          </Stat>
          <Stat label="Target">
            <Money value={s.target} className="text-[1.9rem] leading-none" />
          </Stat>
        </div>
        <Bar className="mt-3" value={Math.max(0, shownSaved)} max={s.target} color="green" height={14} />
        <p className="mt-2 text-xs font-semibold text-muted">
          {shownSaved >= s.target
            ? `Ahead of target by ${rupees(shownSaved - s.target)}.`
            : `${rupees(s.target - shownSaved)} short of target.`}
          {isCurrent && (
            <>
              {" "}
              Saved so far: <Money value={s.savedSoFar} className="text-ink" />.
            </>
          )}
        </p>
      </Panel>

      {/* income */}
      <Panel title="Income" jp="収入" right={<Money value={s.income} className="text-lg" />}>
        {ins.length === 0 ? (
          <Empty>No income lands this month.</Empty>
        ) : (
          <ul className="space-y-1.5">
            {ins.map((i) => (
              <li key={i.label + i.date} className="flex items-center gap-2 text-sm">
                <span className={cx("font-bold", i.date > today && "text-muted")}>{i.label}</span>
                <span className="text-[11px] font-semibold text-muted">
                  {dayLabel(i.date)}
                  {i.date > today ? "· upcoming" : ""}
                </span>
                <Money value={i.amount} className="ml-auto" />
              </li>
            ))}
          </ul>
        )}
        <p className="mt-3 border-t border-line pt-2 text-[11px] font-semibold text-muted">
          Salary {rupees(plan.salary.gross)} − office scheme {rupees(plan.salary.officeScheme)} = {rupees(takeHome(plan))}{" "}
          take-home − parents {rupees(plan.salary.toParents)} = <b className="text-ink">{rupees(salaryShare(plan))} yours</b>.
          Laptop fund {rupees(plan.laptopFund)} is kept separate.
        </p>
      </Panel>

      {/* fixed payments */}
      <Panel title="Fixed payments" jp="固定費" right={<Money value={fixedTotal} className="text-lg" />}>
        {fixedTotal > plan.installmentWarn && (
          <p className="mb-2 flex items-center gap-2 rounded-xl border border-red bg-red/10 px-2 py-1.5 text-xs font-bold text-red-ink">
            <TriangleAlert size={14} /> Above your {rupees(plan.installmentWarn)} installment limit.
          </p>
        )}
        {fixed.length ? (
          <ul className="divide-y divide-line">
            {fixed.map((d) => (
              <DueRow key={d.c.id} c={d.c} month={month} paid={d.paid} />
            ))}
          </ul>
        ) : (
          <Empty>No installments this month.</Empty>
        )}
      </Panel>

      {oneTime.length > 0 && (
        <Panel title="One-time" jp="特別" right={<Money value={oneTime.reduce((a, d) => a + d.c.amount, 0)} className="text-lg" />}>
          <ul className="divide-y divide-line">
            {oneTime.map((d) => (
              <DueRow key={d.c.id} c={d.c} month={month} paid={d.paid} />
            ))}
          </ul>
        </Panel>
      )}

      {/* budget vs actual */}
      <Panel title="Budget vs actual" jp="予算">
        <div className="mb-3 flex items-baseline gap-2">
          <Money value={s.spent} className={cx("text-[1.6rem] leading-none", s.spent > s.cap && "text-red-ink")} />
          <span className="text-sm font-bold text-muted">
            of <Money value={s.cap} /> everyday cap
          </span>
        </div>
        <Bar value={s.spent} max={s.cap} color="yellow" height={14} />
        <ul className="mt-4 space-y-3">
          {plan.categories.map((cat) => {
            const spent = spentInMonth(expenses, month, cat.id);
            const budget = budgets[cat.id] ?? 0;
            return (
              <li key={cat.id}>
                <div className="mb-1 flex items-baseline gap-2 text-sm">
                  <span>{cat.emoji}</span>
                  <span className="font-bold">{cat.name}</span>
                  <span className={cx("ml-auto text-xs font-semibold", spent > budget ? "text-red-ink" : "text-muted")}>
                    <Money value={spent} className="text-sm text-ink" /> / <Money value={budget} />
                  </span>
                </div>
                <Bar value={spent} max={budget} color={cat.color} height={10} />
              </li>
            );
          })}
        </ul>
      </Panel>

      <Panel title="Expenses" jp="支出" right={<span className="text-xs font-bold text-muted">{items.length} logged</span>}>
        <ExpenseList items={items} empty="Nothing logged this month." />
      </Panel>
      </div>
    </div>
  );
}

function Stat({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <p className="mb-1 text-[11px] font-extrabold tracking-wide text-muted uppercase">{label}</p>
      {children}
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { Lock, Pencil, Plus, Trash2 } from "lucide-react";
import { useData } from "@/lib/data";
import { addMonths, monthLabel, monthRange } from "@/lib/dates";
import { budgetsFor, salaryShare } from "@/lib/finance";
import { rupees } from "@/lib/format";
import type { Category, Commitment, Plan, Pot } from "@/lib/types";
import { CommitmentEditor, blankCommitment } from "@/components/CommitmentEditor";
import { MODE_LABEL } from "@/components/DueRow";
import { useUI } from "@/components/UIProvider";
import { Money, PageTitle, Panel, cx } from "@/components/ui";

const COLORS = ["green", "red", "violet", "yellow", "cyan", "pink"];

export default function SettingsPage() {
  const { plan, savePlan, commitments, pots, lock } = useData();
  const { toast } = useUI();
  const [draft, setDraft] = useState<Plan>(plan);
  const [editing, setEditing] = useState<Commitment | null>(null);
  const dirty = JSON.stringify(draft) !== JSON.stringify(plan);
  const set = <K extends keyof Plan>(k: K, v: Plan[K]) => setDraft((d) => ({ ...d, [k]: v }));
  const periodMonths = monthRange(draft.periodStart, draft.periodEnd);
  const wideMonths = monthRange(addMonths(draft.periodStart, -1), addMonths(draft.periodEnd, 1));

  function setCat(i: number, patch: Partial<Category>) {
    set("categories", draft.categories.map((c, j) => (j === i ? { ...c, ...patch } : c)));
  }

  function save() {
    savePlan(draft);
    toast("Plan saved");
  }

  return (
    <div className="mx-auto w-full max-w-[1600px] pb-16">
      <PageTitle title="Settings" jp="設定" />

      <div className="gap-5 lg:columns-2 2xl:columns-3 [&>*]:mb-4 [&>*]:break-inside-avoid lg:[&>*]:mb-5">
      <Panel title="Period & cash" jp="期間">
        <Grid>
          <Field label="Start month">
            <MonthSelect value={draft.periodStart} onChange={(v) => set("periodStart", v)} />
          </Field>
          <Field label="End month">
            <MonthSelect value={draft.periodEnd} onChange={(v) => set("periodEnd", v)} />
          </Field>
          <Field label="Cash on hand">
            <Num value={draft.openingCash} onChange={(v) => set("openingCash", v)} />
          </Field>
          <Field label="…as of">
            <input type="date" className="field" value={draft.openingDate} onChange={(e) => set("openingDate", e.target.value)} />
          </Field>
          <Field label="Laptop fund (kept separate)">
            <Num value={draft.laptopFund} onChange={(v) => set("laptopFund", v)} />
          </Field>
        </Grid>
      </Panel>

      <Panel title="Salary" jp="給料">
        <Grid>
          <Field label="Gross / month">
            <Num value={draft.salary.gross} onChange={(v) => set("salary", { ...draft.salary, gross: v })} />
          </Field>
          <Field label="Office savings scheme">
            <Num value={draft.salary.officeScheme} onChange={(v) => set("salary", { ...draft.salary, officeScheme: v })} />
          </Field>
          <Field label="To parents">
            <Num value={draft.salary.toParents} onChange={(v) => set("salary", { ...draft.salary, toParents: v })} />
          </Field>
          <Field label="Lands on day">
            <Num value={draft.salary.creditDay} onChange={(v) => set("salary", { ...draft.salary, creditDay: Math.min(31, Math.max(1, v)) })} />
          </Field>
        </Grid>
        <p className="mt-2 text-xs font-semibold text-muted">
          Yours each month: <Money value={salaryShare(draft)} className="text-ink" />. Tap the months it lands in:
        </p>
        <Chips
          options={wideMonths}
          selected={draft.salary.months}
          onToggle={(m) =>
            set("salary", {
              ...draft.salary,
              months: draft.salary.months.includes(m) ? draft.salary.months.filter((x) => x !== m) : [...draft.salary.months, m].sort(),
            })
          }
        />
      </Panel>

      <Panel title="Other income" jp="臨時収入">
        <div className="space-y-2">
          {draft.incomes.map((inc, i) => (
            <div key={inc.id} className="grid grid-cols-[1fr_1fr_auto] items-center gap-2 sm:grid-cols-[1fr_6rem_8.5rem_auto]">
              <input
                className="field col-span-3 text-sm sm:col-span-1"
                value={inc.label}
                onChange={(e) => set("incomes", draft.incomes.map((x, j) => (j === i ? { ...x, label: e.target.value } : x)))}
                aria-label="Income label"
              />
              <Num value={inc.amount} onChange={(v) => set("incomes", draft.incomes.map((x, j) => (j === i ? { ...x, amount: v } : x)))} />
              <input
                type="date"
                className="field text-sm"
                value={inc.date}
                onChange={(e) => set("incomes", draft.incomes.map((x, j) => (j === i ? { ...x, date: e.target.value } : x)))}
                aria-label="Income date"
              />
              <IconBtn label="Remove income" onClick={() => set("incomes", draft.incomes.filter((_, j) => j !== i))}>
                <Trash2 size={15} />
              </IconBtn>
            </div>
          ))}
        </div>
        <button
          className="btn mt-3 px-2.5 py-1 text-xs"
          onClick={() =>
            set("incomes", [...draft.incomes, { id: `inc-${Date.now().toString(36)}`, label: "New income", amount: 0, date: `${draft.periodStart}-01` }])
          }
        >
          <Plus size={14} /> Add income
        </button>
      </Panel>

      <Panel title="Monthly budget" jp="予算">
        <Grid>
          <Field label="Normal month cap">
            <Num value={draft.monthlyCap} onChange={(v) => set("monthlyCap", v)} />
          </Field>
          <Field label="Trip month cap">
            <Num value={draft.tripMonthCap} onChange={(v) => set("tripMonthCap", v)} />
          </Field>
        </Grid>
        <p className="mt-3 mb-1 text-[11px] font-extrabold tracking-wide text-muted uppercase">Trip months</p>
        <Chips
          options={periodMonths}
          selected={draft.tripMonths}
          onToggle={(m) => set("tripMonths", draft.tripMonths.includes(m) ? draft.tripMonths.filter((x) => x !== m) : [...draft.tripMonths, m].sort())}
        />
        <p className="mt-4 mb-1 text-[11px] font-extrabold tracking-wide text-muted uppercase">Categories</p>
        <div className="space-y-3">
          {draft.categories.map((c, i) => (
            <div key={c.id} className="rounded-2xl border border-line-strong p-2.5">
              <div className="grid grid-cols-[3rem_1fr_3.5rem_auto] gap-2">
                <input className="field px-1 text-center text-lg" value={c.emoji} onChange={(e) => setCat(i, { emoji: e.target.value })} aria-label="Emoji" />
                <input className="field text-sm" value={c.name} onChange={(e) => setCat(i, { name: e.target.value })} aria-label="Category name" />
                <input className="field jp px-1 text-center text-sm" value={c.jp} onChange={(e) => setCat(i, { jp: e.target.value })} aria-label="Japanese label" />
                <IconBtn
                  label="Remove category"
                  onClick={() => confirm(`Remove ${c.name}? Past expenses keep their amount.`) && set("categories", draft.categories.filter((_, j) => j !== i))}
                >
                  <Trash2 size={15} />
                </IconBtn>
              </div>
              <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3">
                {c.isRemainder ? (
                  <p className="col-span-2 self-center text-xs font-semibold text-muted">
                    Gets what&apos;s left under the cap: {rupees(budgetsFor(draft, draft.periodStart)[c.id] ?? 0)} in {monthLabel(draft.periodStart)}
                  </p>
                ) : (
                  <>
                    <Field label="Monthly">
                      <Num value={c.monthly} onChange={(v) => setCat(i, { monthly: v })} />
                    </Field>
                    <Field label="Trip month">
                      <input
                        className="field num"
                        inputMode="numeric"
                        placeholder="same"
                        value={c.tripMonthly ?? ""}
                        onChange={(e) => setCat(i, { tripMonthly: e.target.value === "" ? null : Number(e.target.value.replace(/\D/g, "")) })}
                      />
                    </Field>
                  </>
                )}
                <Field label="Color">
                  <div className="flex gap-1 pt-1">
                    {COLORS.map((col) => (
                      <button
                        key={col}
                        aria-label={col}
                        onClick={() => setCat(i, { color: col })}
                        className={cx("h-6 w-6 rounded-full border", c.color === col ? "border-line" : "border-transparent")}
                        style={{ background: `var(--${col})` }}
                      />
                    ))}
                  </div>
                </Field>
              </div>
              <label className="mt-2 flex items-center gap-2 text-xs font-bold">
                <input
                  type="checkbox"
                  checked={!!c.isRemainder}
                  onChange={(e) => setCat(i, { isRemainder: e.target.checked || undefined })}
                />
                Fun / leftover bucket (budget = cap minus the rest)
              </label>
              <label className="mt-1 flex items-center gap-2 text-xs font-bold">
                <input
                  type="checkbox"
                  checked={c.period === "month"}
                  onChange={(e) => setCat(i, { period: e.target.checked ? "month" : undefined })}
                />
                Monthly allowance (kept out of the weekly number, with a &ldquo;mark used&rdquo; button)
              </label>
            </div>
          ))}
        </div>
        <button
          className="btn mt-3 px-2.5 py-1 text-xs"
          onClick={() =>
            set("categories", [
              ...draft.categories,
              { id: `cat-${Date.now().toString(36)}`, name: "New", jp: "他", emoji: "🛒", monthly: 0, color: "cyan" },
            ])
          }
        >
          <Plus size={14} /> Add category
        </button>
      </Panel>

      <Panel title="Targets & goal" jp="目標">
        <div className="grid grid-cols-3 gap-2">
          {periodMonths.map((m) => (
            <Field key={m} label={`Save in ${monthLabel(m)}`}>
              <Num value={draft.savingsTargets[m] ?? 0} onChange={(v) => set("savingsTargets", { ...draft.savingsTargets, [m]: v })} />
            </Field>
          ))}
        </div>
        <Grid>
          <Field label="Goal by end of period">
            <Num value={draft.goal} onChange={(v) => set("goal", v)} />
          </Field>
          <Field label="Milestone bursts (₹, comma separated)">
            <input
              className="field num"
              defaultValue={draft.milestones.join(", ")}
              onBlur={(e) =>
                set(
                  "milestones",
                  e.target.value
                    .split(",")
                    .map((x) => Number(x.replace(/\D/g, "")))
                    .filter((x) => x > 0)
                    .sort((a, b) => a - b),
                )
              }
            />
          </Field>
        </Grid>
      </Panel>

      <Panel title="Rules" jp="ルール">
        <Grid>
          <Field label="Warn if installments exceed">
            <Num value={draft.installmentWarn} onChange={(v) => set("installmentWarn", v)} />
          </Field>
          <Field label="Wishlist anything over">
            <Num value={draft.wishlistThreshold} onChange={(v) => set("wishlistThreshold", v)} />
          </Field>
          <Field label="Wishlist wait (hours)">
            <Num value={draft.wishlistHours} onChange={(v) => set("wishlistHours", Math.max(1, v))} />
          </Field>
        </Grid>
      </Panel>

      <Panel
        title="Planned items & EMIs"
        jp="予定"
        right={
          <button className="btn px-2 py-1 text-xs btn-primary" onClick={() => setEditing(blankCommitment(plan.periodStart, commitments.length))}>
            <Plus size={14} strokeWidth={3} /> Add
          </button>
        }
      >
        <p className="mb-2 text-xs font-semibold text-muted">These save immediately.</p>
        <ul className="divide-y divide-line">
          {commitments.map((c) => (
            <li key={c.id} className="flex items-center gap-2 py-2 text-sm">
              {c.mustPay && <Lock size={12} strokeWidth={3} aria-label="Must pay" />}
              <span className="font-bold">{c.name}</span>
              <span className="text-[11px] font-semibold text-muted">
                {MODE_LABEL[c.mode]} · {c.months.length > 1 ? `${monthLabel(c.months[0])}–${monthLabel(c.months[c.months.length - 1])}` : monthLabel(c.months[0])}
              </span>
              <Money value={c.amount} className="ml-auto" />
              <IconBtn label={`Edit ${c.name}`} onClick={() => setEditing(c)}>
                <Pencil size={14} />
              </IconBtn>
            </li>
          ))}
        </ul>
      </Panel>

      <PotsEditor pots={pots} commitments={commitments} />

      <Panel title="Device" jp="端末">
        <div className="flex items-center gap-2 text-sm">
          <span className="font-semibold text-muted">Lock this device and clear its offline copy.</span>
          <button className="btn ml-auto px-3 py-1.5 text-xs" onClick={lock}>
            Lock
          </button>
        </div>
      </Panel>

      </div>

      {dirty && (
        <div className="fixed inset-x-0 bottom-[calc(84px+env(safe-area-inset-bottom))] z-30 flex justify-center px-4 md:bottom-6 md:pl-56">
          <div className="panel anim-pop flex w-full max-w-md items-center gap-2 p-2">
            <span className="flex-1 pl-2 text-sm font-bold">Unsaved changes</span>
            <button className="btn px-3 py-1.5 text-sm" onClick={() => setDraft(plan)}>
              Reset
            </button>
            <button className="btn px-4 py-1.5 text-sm btn-primary" onClick={save}>
              Save plan
            </button>
          </div>
        </div>
      )}

      <CommitmentEditor item={editing} onClose={() => setEditing(null)} />
    </div>
  );
}

function PotsEditor({ pots, commitments }: { pots: Pot[]; commitments: Commitment[] }) {
  const { savePot, deletePot } = useData();
  return (
    <Panel title="Set-aside pots" jp="積立">
      <p className="mb-2 text-xs font-semibold text-muted">These save immediately. Paying a linked item uses the pot&apos;s money.</p>
      <div className="space-y-3">
        {pots.map((p) => (
          <div key={p.id} className="rounded-2xl border border-line-strong p-2.5">
            <div className="grid grid-cols-[1fr_3.5rem_6rem_auto] gap-2">
              <input className="field text-sm" defaultValue={p.name} onBlur={(e) => savePot({ ...p, name: e.target.value || p.name })} aria-label="Pot name" />
              <input className="field jp px-1 text-center text-sm" defaultValue={p.jp} onBlur={(e) => savePot({ ...p, jp: e.target.value })} aria-label="Japanese label" />
              <input
                className="field num text-sm"
                inputMode="numeric"
                defaultValue={p.target}
                onBlur={(e) => savePot({ ...p, target: Number(e.target.value.replace(/\D/g, "")) || p.target })}
                aria-label="Target"
              />
              <IconBtn label="Delete pot" onClick={() => confirm(`Delete the ${p.name} pot?`) && deletePot(p.id)}>
                <Trash2 size={15} />
              </IconBtn>
            </div>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {commitments
                .filter((c) => c.mode === "cash")
                .map((c) => {
                  const on = p.commitmentIds.includes(c.id);
                  return (
                    <button
                      key={c.id}
                      onClick={() =>
                        savePot({ ...p, commitmentIds: on ? p.commitmentIds.filter((x) => x !== c.id) : [...p.commitmentIds, c.id] })
                      }
                      className={cx("rounded-full border px-2 py-0.5 text-[11px] font-bold", on ? "chip-on" : "border-line-strong")}
                    >
                      {c.name}
                    </button>
                  );
                })}
            </div>
          </div>
        ))}
      </div>
      <button
        className="btn mt-3 px-2.5 py-1 text-xs"
        onClick={() =>
          savePot({ id: `pot-${Date.now().toString(36)}`, name: "New pot", jp: "積立", target: 10000, saved: 0, commitmentIds: [], order: pots.length })
        }
      >
        <Plus size={14} /> Add pot
      </button>
    </Panel>
  );
}

function Grid({ children }: { children: ReactNode }) {
  return <div className="mt-2 grid grid-cols-2 gap-3">{children}</div>;
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return (
    <label className="block min-w-0">
      <span className="mb-1 block truncate text-[11px] font-extrabold tracking-wide text-muted uppercase">{label}</span>
      {children}
    </label>
  );
}

function Num({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  return (
    <input
      className="field num"
      inputMode="numeric"
      value={value === 0 ? "0" : value || ""}
      onChange={(e) => onChange(Number(e.target.value.replace(/\D/g, "")) || 0)}
    />
  );
}

function MonthSelect({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return <input type="month" className="field" value={value} onChange={(e) => e.target.value && onChange(e.target.value)} />;
}

function Chips({ options, selected, onToggle }: { options: string[]; selected: string[]; onToggle: (m: string) => void }) {
  return (
    <div className="mt-1 flex flex-wrap gap-1.5">
      {options.map((m) => (
        <button
          key={m}
          onClick={() => onToggle(m)}
          aria-pressed={selected.includes(m)}
          className={cx(
            "rounded-full border px-2.5 py-0.5 text-xs font-bold",
            selected.includes(m) ? "chip-on" : "border-line-strong",
          )}
        >
          {monthLabel(m)} {m.slice(2, 4)}
        </button>
      ))}
    </div>
  );
}

function IconBtn({ label, onClick, children }: { label: string; onClick: () => void; children: ReactNode }) {
  return (
    <button aria-label={label} onClick={onClick} className="rounded p-1.5 text-muted hover:text-ink">
      {children}
    </button>
  );
}

