          <button
            className="btn px-2 py-1 text-xs btn-primary"
            onClick={() => setEditing(blankCommitment(monthOf(today) < plan.periodStart ? plan.periodStart : monthOf(today), commitments.length))}
          >
            <Plus size={14} strokeWidth={3} /> Add
