import { COOKIE } from "@/lib/server/session";

export async function POST() {
  return Response.json({ ok: true }, { headers: { "Set-Cookie": `${COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0` } });
}

import type { Op } from "@/lib/ops";
import { applyOps, validate } from "@/lib/server/db";
import { hasSession } from "@/lib/server/session";

export async function POST(req: Request) {
  if (!hasSession(req)) return Response.json({ error: "locked" }, { status: 401 });
  const body = (await req.json().catch(() => null)) as { ops?: unknown } | null;
  const ops = body?.ops;
  if (!Array.isArray(ops) || ops.length > 200) return Response.json({ error: "ops must be an array (max 200)" }, { status: 400 });
  for (const op of ops) {
    const err = validate(op);
    if (err) return Response.json({ error: err }, { status: 400 });
  }
  try {
    await applyOps(ops as Op[]);
    return Response.json({ ok: true });
  } catch (e) {
    return Response.json({ error: (e as Error).message }, { status: 500 });
  }
}

import { loadAll } from "@/lib/server/db";
import { hasSession } from "@/lib/server/session";

export async function GET(req: Request) {
  if (!hasSession(req)) return Response.json({ error: "locked" }, { status: 401 });
  // The client's local date, used only to stamp "cash on hand as of" when seeding.
  const today = new URL(req.url).searchParams.get("today") ?? "";
  try {
    const data = await loadAll(/^\d{4}-\d{2}-\d{2}$/.test(today) ? today : new Date().toISOString().slice(0, 10));
    return Response.json(data, { headers: { "Cache-Control": "no-store" } });
  } catch (e) {
    return Response.json({ error: (e as Error).message }, { status: 500 });
  }
}

import { COOKIE, MAX_AGE, clearFailures, makeToken, passwordMatches, recordFailure, tooManyFailures } from "@/lib/server/session";

export async function POST(req: Request) {
  const { password } = (await req.json().catch(() => ({}))) as { password?: unknown };
  if (typeof password !== "string" || !password) return Response.json({ error: "Enter the password." }, { status: 400 });

  try {
    if (await tooManyFailures())
      return Response.json({ error: "Too many wrong attempts. Try again in 15 minutes." }, { status: 429 });
    if (!passwordMatches(password)) {
      await recordFailure();
      await new Promise((r) => setTimeout(r, 600));
      return Response.json({ error: "Wrong password." }, { status: 401 });
    }
    await clearFailures();
  } catch (e) {
    return Response.json({ error: (e as Error).message }, { status: 500 });
  }

  const secure = process.env.NODE_ENV === "production" ? "; Secure" : "";
  return Response.json(
    { ok: true },
    { headers: { "Set-Cookie": `${COOKIE}=${makeToken()}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${MAX_AGE}${secure}` } },
  );
}

