            <Money value={ci.biggest.amount} className="text-ink" /> on {dayLabel(ci.biggest.date)}.
          </p>
        )}
      </Panel>
      </div>
    </div>
  );
}

function Mini({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="panel p-3">
      <p className="mb-1 text-[10px] leading-tight font-extrabold tracking-wide text-muted uppercase">{label}</p>
      {children}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Hourglass, ShoppingBag, Trash2 } from "lucide-react";
import { useData } from "@/lib/data";
import { rupees } from "@/lib/format";
import type { WishItem } from "@/lib/types";
import { useNow, useUI } from "@/components/UIProvider";
import { Bar, Empty, Money, PageTitle, Panel, cx } from "@/components/ui";

export default function WishlistPage() {
  const { plan, wishlist, addWish } = useData();
  const { toast } = useUI();
  const now = useNow(1000);
  const [name, setName] = useState("");
  const [amount, setAmount] = useState("");
  const [cat, setCat] = useState(plan.categories.find((c) => c.isRemainder)?.id ?? plan.categories[0]?.id);
  const waiting = wishlist.filter((w) => w.status === "waiting");
  const done = wishlist.filter((w) => w.status !== "waiting");
  const avoided = wishlist.filter((w) => w.status === "dropped").reduce((a, w) => a + w.amount, 0);
  const n = Number(amount) || 0;

  function add() {
    if (!name.trim() || !n || !cat) return;
    addWish({ name: name.trim(), amount: n, categoryId: cat });
    setName("");
    setAmount("");
    toast(`Timer started: ${plan.wishlistHours}h to decide`);
  }

  return (
    <div className="mx-auto w-full max-w-[1600px] space-y-4">
      <PageTitle title="Wishlist" jp="欲しい物" sub={`${plan.wishlistHours}h rule · over ${rupees(plan.wishlistThreshold)}`} />

      <div className="page-grid">
      <section className="panel glow flex items-center gap-4 p-4">
        <div className="flex-1">
          <p className="text-[11px] font-extrabold tracking-wide text-muted uppercase">Avoided by deleting</p>
          <Money value={avoided} className="text-[2.6rem] leading-none text-green-ink" />
        </div>
        <span aria-hidden className="jp rotate-6 text-3xl text-pink-ink">
          我慢
        </span>
      </section>

      <Panel title="Want something?" jp="待て">
        <div className="grid grid-cols-[1fr_7rem] gap-2">
          <input className="field" placeholder="What is it?" value={name} onChange={(e) => setName(e.target.value)} />
          <input
            className="field num"
            placeholder="₹"
            inputMode="numeric"
            value={amount}
            onChange={(e) => setAmount(e.target.value.replace(/\D/g, ""))}
          />
        </div>
        <div className="mt-2 flex flex-wrap gap-1.5">
          {plan.categories.map((c) => (
            <button
              key={c.id}
              onClick={() => setCat(c.id)}
              className={cx(
                "rounded-full border px-2.5 py-1 text-xs font-bold",
                cat === c.id ? "chip-on" : "border-line-strong",
              )}
            >
              {c.emoji} {c.name}
            </button>
          ))}
        </div>
        <button className="btn mt-3 w-full py-2.5 btn-primary" onClick={add} disabled={!name.trim() || !n}>
          <Hourglass size={16} strokeWidth={2.5} /> Start the {plan.wishlistHours}h timer
        </button>
      </Panel>

      <Panel title="Cooling off" jp="冷却中">
        {waiting.length === 0 ? (
          <Empty>Nothing waiting. Impulse buys over {rupees(plan.wishlistThreshold)} land here from Quick add.</Empty>
        ) : (
          <ul className="space-y-4">
            {waiting.map((w) => (
              <WishRow key={w.id} w={w} now={now} hours={plan.wishlistHours} />
            ))}
          </ul>
        )}
      </Panel>

      {done.length > 0 && (
        <Panel title="History" jp="履歴">
          <ul className="divide-y divide-line">
            {done.slice(0, 20).map((w) => (
              <li key={w.id} className="flex items-center gap-2 py-2 text-sm">
                <span className={cx("font-bold", w.status === "dropped" && "line-through")}>{w.name}</span>
                <span
                  className={cx(
                    "rounded-full px-1.5 text-[10px] font-extrabold uppercase",
                    w.status === "dropped" ? "bg-green/18 text-green-ink" : "bg-sunk text-muted",
                  )}
                >
                  {w.status === "dropped" ? "avoided" : "bought"}
                </span>
                <Money value={w.amount} className="ml-auto" />
              </li>
            ))}
          </ul>
        </Panel>
      )}
      </div>
    </div>
  );
}

function WishRow({ w, now, hours }: { w: WishItem; now: number; hours: number }) {
  const { resolveWish } = useData();
  const { toast, celebrate } = useUI();
  const total = hours * 3600_000;
  const left = Math.max(0, w.createdAt + total - now);
  const ready = left === 0;
  const h = Math.floor(left / 3600_000);
  const m = Math.floor((left % 3600_000) / 60_000);
  const s = Math.floor((left % 60_000) / 1000);

  return (
    <li>
      <div className="flex items-baseline gap-2">
        <span className="font-extrabold">{w.name}</span>
        <Money value={w.amount} className="ml-auto text-lg" />
      </div>
      <Bar value={total - left} max={total} color={ready ? "green" : "cyan"} height={10} className="mt-1.5" />
      <div className="mt-2 flex items-center gap-2">
        <span className={cx("num min-w-0 flex-1 text-sm", ready ? "text-green-ink" : "text-muted")}>
          {ready ? "Time\u2019s up. Still want it?" : `${h}h ${String(m).padStart(2, "0")}m ${String(s).padStart(2, "0")}s`}
        </span>
        <button
          className="btn px-2.5 py-1 text-xs whitespace-nowrap btn-ok"
          onClick={() => {
            resolveWish(w, "dropped");
            celebrate({ title: `+${rupees(w.amount)}`, jp: "我慢!", sub: `Didn't buy ${w.name}. Saved instead.` });
          }}
        >
          <Trash2 size={13} /> Don&apos;t buy
        </button>
        <button
          className="btn px-2.5 py-1 text-xs whitespace-nowrap"
          disabled={!ready}
          title={ready ? undefined : "Locked until the timer ends"}
          onClick={() => {
            resolveWish(w, "bought");
            toast(`${w.name} logged as an expense`);
          }}
        >
          <ShoppingBag size={13} /> Bought
        </button>
      </div>
    </li>
  );
}

"use client";

import { useState } from "react";
import { useData } from "@/lib/data";
import { daysInMonth, monthLabel, parseDay } from "@/lib/dates";
import { monthsLeft, projection, remainingPayments } from "@/lib/finance";
import { rupees } from "@/lib/format";
import { ProjectionChart } from "@/components/ProjectionChart";
import { useToday } from "@/components/UIProvider";
import { Money, PageTitle, Panel, cx } from "@/components/ui";

export default function ProjectionPage() {
  const { plan, expenses, commitments } = useData();
  const today = useToday();
  const [table, setTable] = useState(false);
  const rows = projection(plan, expenses, commitments, today);
  const end = rows[rows.length - 1];
  const vsPlan = end.projected - end.plan;
  const vsGoal = end.projected - plan.goal;
  const nMonths = monthsLeft(plan, today);
  const periodEndDay = `${plan.periodEnd}-${daysInMonth(plan.periodEnd)}`;
  const weeksLeft = Math.max(0, Math.ceil((+parseDay(periodEndDay) - +parseDay(today)) / (7 * 864e5)));
  const skippedTotal = commitments
    .filter((c) => c.skipped)
    .reduce((a, c) => a + remainingPayments(c).length * c.amount, 0);

  return (
    <div className="mx-auto w-full max-w-[1600px] space-y-4">
      <PageTitle title="Future" jp="未来" sub={`to end of ${monthLabel(plan.periodEnd, "long")}`} />

      <div className="page-grid">
      <section className="panel glow p-4">
        <p className="text-[11px] font-extrabold tracking-wide text-muted uppercase">Projected savings by {monthLabel(plan.periodEnd)}</p>
        <Money value={end.projected} className="block text-[3rem] leading-tight" />
        <div className="mt-1 flex flex-wrap gap-2 text-xs font-bold">
          <Pill good={vsGoal >= 0}>
            {vsGoal >= 0 ? `${rupees(vsGoal)} above` : `${rupees(-vsGoal)} short of`} the {rupees(plan.goal)} goal
          </Pill>
          {Math.abs(vsPlan) < 1 ? (
            <span className="rounded-xl border border-line-strong bg-panel px-2 py-0.5">● Exactly on plan</span>
          ) : (
            <Pill good={vsPlan > 0}>
              {vsPlan > 0 ? `${rupees(vsPlan)} ahead of` : `${rupees(-vsPlan)} behind`} plan
            </Pill>
          )}
        </div>
        <p className="mt-2 text-[11px] font-semibold text-muted">
          Past months use what you actually spent. This month counts the larger of your spending so far and its budget.
          Future months assume budget plus every planned, unskipped payment. Includes the office payout.
        </p>
      </section>

      <Panel title="Savings arc" jp="軌跡" className="lg:col-span-2 xl:row-span-2">
        <ProjectionChart rows={rows} goal={plan.goal} />
        <button className="mt-2 text-xs font-bold underline" onClick={() => setTable((t) => !t)}>
          {table ? "Hide" : "Show"} as table
        </button>
        {table && (
          <table className="mt-2 w-full text-right text-xs">
            <thead className="text-muted">
              <tr>
                <th className="py-1 text-left">Month end</th>
                <th>Projected</th>
                <th>Plan</th>
                <th>Targets</th>
              </tr>
            </thead>
            <tbody className="num">
              {rows.map((r) => (
                <tr key={r.month} className="border-t border-line">
                  <td className="py-1 text-left font-bold">{monthLabel(r.month)}</td>
                  <td>{rupees(r.projected)}</td>
                  <td>{rupees(r.plan)}</td>
                  <td>{rupees(r.target)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Panel>

      <Panel title="What ₹1k over costs" jp="代償">
        <ul className="space-y-3">
          <Cost label="One slip, ₹1,000 over budget once" value={1000} />
          <Cost label={`₹1,000 over every month (${nMonths} month${nMonths === 1 ? "" : "s"} left)`} value={1000 * nMonths} />
          <Cost label={`₹1,000 over every week (${weeksLeft} weeks left)`} value={1000 * weeksLeft} />
        </ul>
        <p className="mt-3 text-[11px] font-semibold text-muted">
          Every rupee over budget comes straight out of the {monthLabel(plan.periodEnd)} total. A ₹1k-a-week habit is{" "}
          {Math.round(((1000 * weeksLeft) / plan.goal) * 100)}% of your goal.
        </p>
      </Panel>

      {skippedTotal > 0 && (
        <Panel title="Skipped wins" jp="勝利">
          <p className="text-sm font-semibold">
            Skipping planned buys added <Money value={skippedTotal} className="text-green-ink" /> to this projection.
          </p>
        </Panel>
      )}
      </div>
    </div>
  );
}

function Pill({ good, children }: { good: boolean; children: React.ReactNode }) {
  return (
    <span className={cx("rounded-xl border border-line-strong px-2 py-0.5", good ? "bg-green/18 text-green-ink" : "bg-red text-white")}>
      {good ? "▲" : "▼"}
      {children}
    </span>
  );
}

function Cost({ label, value }: { label: string; value: number }) {
  return (
    <li className="flex items-center gap-3">
      <span className="flex-1 text-sm font-bold">{label}</span>
      <Money value={-value} className="text-lg text-red-ink" />
