"use client";

import { useEffect, useState } from "react";
import { Delete, Hourglass, StickyNote } from "lucide-react";
import { useData } from "@/lib/data";
import { budgetsFor, isMonthly, spentInMonth, weekStats } from "@/lib/finance";
import { monthOf } from "@/lib/dates";
import { rupees, rupeesShort } from "@/lib/format";
import type { Category } from "@/lib/types";
import { Money, Sheet, cx, tone } from "./ui";
import { useToday, useUI } from "./UIProvider";

const KEYS = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "00", "0", "del"];

/** Amount → tap a category = saved. Big amounts get one extra step: planned, or 48h wishlist? */
export function QuickAdd({ open, onClose }: { open: boolean; onClose: () => void }) {
  return (
    <Sheet open={open} onClose={onClose} label="Quick add expense">
      {open && <QuickAddBody onClose={onClose} />}
    </Sheet>
  );
}

function QuickAddBody({ onClose }: { onClose: () => void }) {
  const { plan, expenses, addExpense, deleteExpense, addWish } = useData();
  const { toast } = useUI();
  const today = useToday();
  const [raw, setRaw] = useState("");
  const [note, setNote] = useState("");
  const [noteOpen, setNoteOpen] = useState(false);
  const [pending, setPending] = useState<Category | null>(null);
  const [wishName, setWishName] = useState("");

  const amount = Number(raw || 0);
  const week = weekStats(plan, expenses, today);

  function press(k: string) {
    if (k === "del") return setRaw((r) => r.slice(0, -1));
    setRaw((r) => (r + k).replace(/^0+/, "").slice(0, 7));
  }

  // Mac: type digits on the keyboard too.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).tagName === "INPUT") return;
      if (/^\d$/.test(e.key)) setRaw((r) => (r + e.key).replace(/^0+/, "").slice(0, 7));
      else if (e.key === "Backspace") setRaw((r) => r.slice(0, -1));
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  function pick(cat: Category) {
    if (amount <= 0) return;
    if (amount > plan.wishlistThreshold) {
      setWishName(note);
      setPending(cat);
      return;
    }
    save(cat);
  }

  function save(cat: Category) {
    const id = addExpense({ amount, categoryId: cat.id, note: note.trim() || undefined, date: today });
    onClose();
    toast(`${rupees(amount)} · ${cat.name} logged`, { label: "Undo", run: () => deleteExpense(id) });
  }

  function toWishlist(cat: Category) {
    addWish({ name: wishName.trim() || cat.name, amount, categoryId: cat.id });
    onClose();
    toast(`On the wishlist. Decide in ${plan.wishlistHours}h ⏳`);
  }

  if (pending) {
    return (
      <div className="p-5 pt-6">
        <p className="jp text-xs text-pink-ink">ちょっと待って</p>
        <h2 className="display mt-1 text-3xl">Hold up!</h2>
        <p className="mt-2 text-sm font-semibold text-muted">
          <Money value={amount} className="text-ink" /> is over {rupees(plan.wishlistThreshold)}. Was this planned?
        </p>
        <label className="mt-4 block text-xs font-bold uppercase tracking-wide text-muted">
          What is it?
          <input
            className="field mt-1"
            value={wishName}
            onChange={(e) => setWishName(e.target.value)}
            placeholder={pending.name}
          />
        </label>
        <div className="mt-5 grid gap-3">
          <button className="btn py-3 btn-primary" onClick={() => toWishlist(pending)}>
            <Hourglass size={18} strokeWidth={2.5} /> Impulse: wishlist it for {plan.wishlistHours}h
          </button>
          <button className="btn py-3" onClick={() => save(pending)}>
            Planned: log it now
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 pt-5">
      <div className="flex items-baseline gap-2 pr-10">
        <span className="display text-xl">Quick add</span>
        <span aria-hidden className="jp text-xs text-pink-ink">
          記録
        </span>
      </div>

      <div className="mt-2 flex items-center justify-center rounded-3xl bg-gradient-to-br from-pink/12 to-violet/12 py-4">
        <span className={cx("num text-[3.2rem] leading-none", !raw && "text-muted/60")} aria-live="polite">
          <span className="cur">₹</span>
          {raw ? Number(raw).toLocaleString("en-IN") : "0"}
        </span>
      </div>

      {noteOpen ? (
        <input
          className="field mt-2 text-sm"
          placeholder="Note (optional)"
          value={note}
          onChange={(e) => setNote(e.target.value)}
          autoFocus
          enterKeyHint="done"
        />
      ) : (
        <button
          className="mt-2 flex items-center gap-1 text-xs font-bold text-muted"
          onClick={() => setNoteOpen(true)}
        >
          <StickyNote size={14} /> add note
        </button>
      )}

      <div className="mt-3 grid grid-cols-3 gap-2">
        {plan.categories.map((cat) => {
          const monthly = isMonthly(cat);
          const c = week.perCat.find((p) => p.cat.id === cat.id);
          const left = monthly
            ? (budgetsFor(plan, monthOf(today))[cat.id] ?? 0) - spentInMonth(expenses, monthOf(today), cat.id)
            : c
              ? c.budget - c.spent
              : 0;
          return (
            <button
              key={cat.id}
              disabled={amount <= 0}
              onClick={() => pick(cat)}
              className="flex flex-col items-center rounded-2xl border px-1 py-2 text-[13px] leading-tight font-bold transition-transform active:scale-95 disabled:opacity-50"
              style={{
                borderColor: `color-mix(in srgb, ${tone(cat.color)} 40%, transparent)`,
                background: `color-mix(in srgb, ${tone(cat.color)} 12%, var(--panel))`,
              }}
            >
              <span className="text-xl">{cat.emoji}</span>
              <span className="truncate">{cat.name}</span>
              <span className={cx("text-[10px] font-semibold", left < 0 ? "text-red-ink" : "text-muted")}>
                {rupeesShort(left)} left/{monthly ? "mo" : "wk"}
              </span>
            </button>
          );
        })}
      </div>

      <div className="mt-3 grid grid-cols-3 gap-1.5">
        {KEYS.map((k) => (
          <button
            key={k}
            onClick={() => press(k)}
            aria-label={k === "del" ? "Delete digit" : k}
            className="num flex h-12 items-center justify-center rounded-2xl bg-sunk text-xl active:bg-pink/20"
          >
            {k === "del" ? <Delete size={22} /> : k}
          </button>
        ))}
      </div>
      <p className="mt-2 text-center text-[11px] font-semibold text-muted">Type the amount, then tap a category to save.</p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { monthLabel } from "@/lib/dates";
import type { ProjectionRow } from "@/lib/finance";
import { rupees, rupeesShort } from "@/lib/format";

const H = 240;
const M = { top: 16, right: 58, bottom: 26, left: 44 };

const SERIES = [
  { key: "projected", label: "Projected", color: "var(--chart-1)", width: 3, dash: undefined },
  { key: "target", label: "Targets", color: "var(--chart-2)", width: 2, dash: "2 5" },
  { key: "plan", label: "Original plan", color: "var(--muted)", width: 2, dash: "7 5" },
] as const;

/** End-of-month savings: actuals-so-far vs the original plan vs cumulative targets, with the goal line. */
export function ProjectionChart({ rows, goal }: { rows: ProjectionRow[]; goal: number }) {
  const [sel, setSel] = useState<number | null>(null);
  // Draw at the real pixel width so labels stay 11px on a phone and on a Mac.
  const box = useRef<HTMLDivElement>(null);
  const [W, setW] = useState(340);
  useEffect(() => {
    const el = box.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setW(Math.max(280, Math.round(e.contentRect.width))));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const all = rows.flatMap((r) => [r.plan, r.projected, r.target]).concat(goal);
  const yMin = Math.min(0, ...all);
  const step = niceStep((Math.max(...all) * 1.05 - yMin) / 4);
  const yMax = Math.ceil((Math.max(...all) * 1.05) / step) * step;
  const iw = W - M.left - M.right;
  const ih = H - M.top - M.bottom;
  const x = (i: number) => M.left + (rows.length === 1 ? iw / 2 : (i / (rows.length - 1)) * iw);
  const y = (v: number) => M.top + ih - ((v - yMin) / (yMax - yMin)) * ih;
  const ticks: number[] = [];
  for (let t = Math.floor(yMin / step) * step; t <= yMax; t += step) ticks.push(t);
  const path = (k: (typeof SERIES)[number]["key"]) => rows.map((r, i) => `${i ? "L" : "M"}${x(i)},${y(r[k])}`).join("");
  const curIdx = rows.findIndex((r) => r.when === "current");

  // Direct labels at the right edge, nudged apart so they never overlap.
  const last = rows[rows.length - 1];
  const ends = SERIES.map((s) => ({ ...s, y: y(last[s.key]) })).sort((a, b) => a.y - b.y);
  for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i - 1].y < 14) ends[i].y = ends[i - 1].y + 14;

  const s = sel != null ? rows[sel] : null;

  return (
    <div>
      <ul className="mb-2 flex flex-wrap gap-x-4 gap-y-1 text-xs font-bold text-muted">
        {SERIES.map((s) => (
          <li key={s.key} className="flex items-center gap-1.5">
            <svg width="22" height="8" aria-hidden>
              <line x1="1" x2="21" y1="4" y2="4" stroke={s.color} strokeWidth={s.width} strokeDasharray={s.dash} strokeLinecap="round" />
            </svg>
            {s.label}
          </li>
        ))}
        <li className="flex items-center gap-1.5">⭐ Goal {rupeesShort(goal)}</li>
      </ul>
      <div className="relative" ref={box}>
        <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H} className="w-full select-none" role="img" aria-label="Projected savings through the period">
          {ticks.map((t) => (
            <g key={t}>
              <line x1={M.left} x2={W - M.right} y1={y(t)} y2={y(t)} stroke="var(--line)" strokeOpacity={0.1} />
              <text x={M.left - 8} y={y(t) + 4} textAnchor="end" fontSize="11" fontWeight="600" fill="var(--muted)" className="num">
                {rupeesShort(t)}
              </text>
            </g>
          ))}
          {curIdx >= 0 && (
            <rect x={x(curIdx) - 18} y={M.top} width={36} height={ih} fill="var(--yellow)" opacity={0.18} rx={4} />
          )}
          <line x1={M.left} x2={W - M.right} y1={y(goal)} y2={y(goal)} stroke="var(--ink)" strokeWidth={1.5} strokeDasharray="1 4" strokeLinecap="round" />
          <text x={M.left + 4} y={y(goal) - 6} fontSize="11" fontWeight="800" fill="var(--ink)">
            ⭐ Goal
          </text>
          {rows.map((r, i) => (
            <text key={r.month} x={x(i)} y={H - 8} textAnchor="middle" fontSize="12" fontWeight={i === curIdx ? 800 : 600} fill={i === curIdx ? "var(--ink)" : "var(--muted)"}>
              {monthLabel(r.month)}
            </text>
          ))}
          {[...SERIES].reverse().map((s) => (
            <path key={s.key} d={path(s.key)} fill="none" stroke={s.color} strokeWidth={s.width} strokeDasharray={s.dash} strokeLinecap="round" strokeLinejoin="round" />
          ))}
          {rows.map((r, i) => (
            <circle key={r.month} cx={x(i)} cy={y(r.projected)} r={4.5} fill="var(--chart-1)" stroke="var(--panel)" strokeWidth={2} />
          ))}
          {ends.map((e) => (
            <g key={e.key}>
              <line x1={W - M.right + 6} x2={W - M.right + 14} y1={e.y} y2={e.y} stroke={e.color} strokeWidth={3} strokeLinecap="round" />
              <text x={W - M.right + 18} y={e.y + 4} fontSize="11" fontWeight="800" fill="var(--ink)" className="num">
                {rupeesShort(last[e.key])}
              </text>
            </g>
          ))}
          {s && sel != null && (
            <g pointerEvents="none">
              <line x1={x(sel)} x2={x(sel)} y1={M.top} y2={M.top + ih} stroke="var(--line)" strokeOpacity={0.5} />
              {SERIES.map((sr) => (
                <circle key={sr.key} cx={x(sel)} cy={y(s[sr.key])} r={5} fill={sr.color} stroke="var(--panel)" strokeWidth={2} />
              ))}
            </g>
          )}
          {/* hit targets: one column per month */}
          {rows.map((r, i) => (
            <rect
              key={r.month}
              x={x(i) - iw / (rows.length - 1 || 1) / 2}
              y={0}
              width={iw / (rows.length - 1 || 1)}
              height={H}
              fill="transparent"
              onPointerEnter={() => setSel(i)}
              onPointerDown={() => setSel(i)}
              onPointerLeave={(e) => e.pointerType === "mouse" && setSel(null)}
            />
          ))}
        </svg>
        {s && sel != null && (
          <div
            className="panel pointer-events-none absolute top-1 z-10 w-44 px-2.5 py-2 text-xs"
            style={{
              left: `${(x(sel) / W) * 100}%`,
              transform: `translateX(${sel > rows.length / 2 ? "calc(-100% - 10px)" : "10px"})`,
            }}
          >
            <p className="mb-1 font-extrabold">
              End of {monthLabel(s.month, "long")}
              {s.when === "past" ? "" : s.when === "current" ? "(now)" : ""}
            </p>
            {SERIES.map((sr) => (
              <p key={sr.key} className="flex items-center gap-1.5 font-semibold text-muted">
                <span className="inline-block h-2 w-2 rounded-full" style={{ background: sr.color }} />
                {sr.label}
                <span className="num ml-auto text-ink">{rupees(s[sr.key])}</span>
              </p>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function niceStep(raw: number) {
  return [10000, 20000, 25000, 50000, 100000, 200000].find((s) => s >= raw) ?? 500000;
}

"use client";

import { useEffect } from "react";

export function RegisterSW() {
  useEffect(() => {
    if (process.env.NODE_ENV !== "production" || !("serviceWorker" in navigator)) return;
    navigator.serviceWorker.register("/sw.js", { scope: "/", updateViaCache: "none" }).catch(() => {});
  }, []);
  return null;
}

"use client";

import { useState } from "react";
import { Check } from "lucide-react";
import { useData } from "@/lib/data";
import { addMonths, dayInMonth, dayLabel, monthLabel, monthOf } from "@/lib/dates";
import { monthlyAllowance } from "@/lib/finance";
import { rupees } from "@/lib/format";
import type { Category } from "@/lib/types";
import { Bar, Money, Panel, Sheet, cx, tone } from "./ui";
import { useToday, useUI } from "./UIProvider";

/** A category with one monthly allowance (perfume): this month, next month, and "mark used". */
export function MonthlyAllowanceCard({ cat, className }: { cat: Category; className?: string }) {
  const { plan, expenses } = useData();
  const today = useToday();
  const [open, setOpen] = useState(false);
  const month = monthOf(today);
  const next = addMonths(month, 1);
  const now = monthlyAllowance(plan, expenses, cat, month);
  const later = monthlyAllowance(plan, expenses, cat, next);
  const left = now.budget - now.spent;
  const status = now.spent === 0 ? "free" : left > 0 ? "partly" : left === 0 ? "used" : "over";

  return (
    <Panel
      className={className}
      title={
        <span className="flex items-center gap-1.5">
          {cat.emoji} {cat.name}
        </span>
      }
      jp={cat.jp}
      right={<span className="rounded-full bg-sunk px-2 py-0.5 text-[10px] font-extrabold text-muted uppercase">monthly</span>}
    >
      <div className="flex items-end justify-between gap-2">
        <div>
          <p className="label">{monthLabel(month, "long")}</p>
          {status === "used" ? (
            <p className="mt-0.5 flex items-center gap-1 text-lg font-extrabold text-green-ink">
              <Check size={18} strokeWidth={3} /> Used
            </p>
          ) : status === "over" ? (
            <p className="mt-0.5 text-lg font-extrabold text-red-ink">
              Over by <Money value={-left} />
            </p>
          ) : (
            <p className="mt-0.5 text-lg font-extrabold">
              <Money value={left} /> <span className="text-sm text-muted">available</span>
            </p>
          )}
        </div>
        <button className="btn btn-primary px-3.5 py-1.5 text-sm" onClick={() => setOpen(true)}>
          {status === "free" ? "Mark used" : "Log more"}
        </button>
      </div>
      <Bar className="mt-2" value={now.spent} max={now.budget} color={cat.color} />
      {now.entries.length > 0 && (
        <ul className="mt-2 space-y-0.5 text-xs font-semibold text-muted">
          {now.entries.map((e) => (
            <li key={e.id} className="flex justify-between">
              <span className="truncate">{e.note || cat.name}</span>
              <Money value={e.amount} className="text-ink" />
            </li>
          ))}
        </ul>
      )}
      <p className="mt-3 rounded-xl bg-sunk px-3 py-2 text-xs font-semibold text-muted">
        {monthLabel(next)}:{" "}
        {later.spent >= later.budget && later.budget > 0 ? (
          <b className="text-ink">already covered ({rupees(later.spent)} on EMI)</b>
        ) : later.spent > 0 ? (
          <>
            <b className="text-ink">{rupees(later.spent)}</b> pre-booked, {rupees(later.budget - later.spent)} free
          </>
        ) : (
          <>{rupees(later.budget)} free</>
        )}
      </p>
      <MarkUsedSheet cat={cat} open={open} onClose={() => setOpen(false)} suggested={Math.max(left, 0) || now.budget} />
    </Panel>
  );
}

function MarkUsedSheet({
  cat,
  open,
  onClose,
  suggested,
}: {
  cat: Category;
  open: boolean;
  onClose: () => void;
  suggested: number;
}) {
  return (
    <Sheet open={open} onClose={onClose} label={`Log ${cat.name}`}>
      {open && <MarkUsedBody cat={cat} onClose={onClose} suggested={suggested} />}
    </Sheet>
  );
}

function MarkUsedBody({ cat, onClose, suggested }: { cat: Category; onClose: () => void; suggested: number }) {
  const { plan, addExpense } = useData();
  const { toast } = useUI();
  const today = useToday();
  const monthly = plan.categories.find((c) => c.id === cat.id)?.monthly ?? cat.monthly;
  const [amount, setAmount] = useState(String(suggested));
  const [note, setNote] = useState("Decant");
  const [emi, setEmi] = useState(false);
  const [parts, setParts] = useState(2);
  const total = Number(amount) || 0;

  const n = emi ? parts : 1;
  const day = Number(today.slice(8, 10));
  const schedule = Array.from({ length: n }, (_, i) => {
    const base = Math.floor(total / n);
    return {
      amount: i === 0 ? total - base * (n - 1) : base,
      date: i === 0 ? today : dayInMonth(addMonths(monthOf(today), i), day),
    };
  });

  function save() {
    schedule.forEach((p, i) =>
      addExpense({
        amount: p.amount,
        categoryId: cat.id,
        note: n > 1 ? `${note || cat.name} · EMI ${i + 1}/${n}` : note || undefined,
        date: p.date,
      }),
    );
    onClose();
    toast(n > 1 ? `${rupees(total)} split over ${n} months` : `${rupees(total)} · ${cat.name} marked used`);
  }

  return (
    <div className="space-y-4 p-5 pt-6">
      <div>
        <p className="jp text-xs text-pink-ink">{cat.jp}</p>
        <h2 className="display text-2xl">
          {cat.emoji} {cat.name}
        </h2>
      </div>

      <div className="flex flex-wrap gap-2">
        <Preset on={total === monthly && note === "Decant"} onClick={() => (setAmount(String(monthly)), setNote("Decant"), setEmi(false))}>
          Decant · {rupees(monthly)}
        </Preset>
        <Preset
          on={total === monthly * 2 && note === "Full bottle"}
          onClick={() => (setAmount(String(monthly * 2)), setNote("Full bottle"), setEmi(true), setParts(2))}
        >
          Full bottle · {rupees(monthly * 2)}
        </Preset>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <label>
          <span className="label mb-1">Amount</span>
          <input className="field num" inputMode="numeric" value={amount} onChange={(e) => setAmount(e.target.value.replace(/\D/g, ""))} />
        </label>
