/* ---------- local persistence: open instantly, log offline ---------- */

const CACHE = "kb.cache.v1";
const QUEUE = "kb.queue.v1";

function readJSON<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : null;
  } catch {
    return null;
  }
}
function writeJSON(key: string, v: unknown) {
  try {
    if (v == null) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify(v));
  } catch {}
}

const EMPTY: Snapshot = {
  plan: null as unknown as Plan,
  meta: { lastMilestone: 0, celebrated: [] },
  expenses: [],
  commitments: [],
  pots: [],
  wishlist: [],
};

function initial(): DataState {
  const base = { status: "loading" as Status, error: null, pending: 0, offline: false };
  if (typeof window === "undefined") return { ...EMPTY, ...base };
  if (DEMO) return { ...demoSnapshot(), ...base, status: "ready" };
  const cache = readJSON<Snapshot>(CACHE);
  const queue = readJSON<Op[]>(QUEUE) ?? [];
  if (!cache?.plan) return { ...EMPTY, ...base };
  cache.plan = migratePlan(cache.plan);
  return { ...queue.reduce(applyOp, cache), ...base, status: "ready", pending: queue.length };
}

export function DataProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<DataState>(initial);
  const latest = useRef(state);
  useEffect(() => {
    latest.current = state;
  }, [state]);
  const queue = useRef<Op[]>([]);
  const busy = useRef(false);
  const again = useRef(false);
  const retry = useRef<ReturnType<typeof setTimeout>>(undefined);

  const lockLocal = useCallback(() => {
    queue.current = [];
    writeJSON(QUEUE, null);
    writeJSON(CACHE, null);
    setState({ ...EMPTY, status: "locked", error: null, pending: 0, offline: false });
  }, []);

  const syncRef = useRef<() => Promise<void>>(() => Promise.resolve());
  const sync = useCallback(async (): Promise<void> => {
    if (DEMO) return;
    if (busy.current) {
      again.current = true; // run once more when the current pass ends
      return;
    }
    busy.current = true;
    clearTimeout(retry.current);
    try {
      // 1. push queued changes, oldest first
      while (queue.current.length) {
        const batch = queue.current.slice(0, 100);
        const res = await fetch("/api/mutate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ops: batch }),
        });
        if (res.status === 401) return lockLocal();
        if (res.status === 400) console.error("[sync] server rejected changes", await res.text());
        else if (!res.ok) throw new Error(((await res.json().catch(() => ({}))) as { error?: string }).error ?? `HTTP ${res.status}`);
        queue.current = queue.current.slice(batch.length);
        writeJSON(QUEUE, queue.current);
        setState((s) => ({ ...s, pending: queue.current.length }));
      }
      // 2. pull the latest (picks up changes made on the other device)
      const res = await fetch(`/api/data?today=${dayKey()}`, { cache: "no-store" });
      if (res.status === 401) return lockLocal();
      if (!res.ok) throw new Error(((await res.json().catch(() => ({}))) as { error?: string }).error ?? `HTTP ${res.status}`);
      const snap = (await res.json()) as Snapshot;
      writeJSON(CACHE, snap);
      const merged = queue.current.reduce(applyOp, snap); // anything logged mid-fetch stays visible
      setState((s) => ({ ...s, ...merged, status: "ready", error: null, offline: false, pending: queue.current.length }));
    } catch (e) {
      const offline = !navigator.onLine;
      const msg = (e as Error).message;
      setState((s) =>
        s.status === "ready"
          ? { ...s, offline: true }
          : { ...s, status: "error", error: offline ? "You're offline and nothing is cached yet." : msg },
      );
      retry.current = setTimeout(() => void syncRef.current(), 15_000);
    } finally {
      busy.current = false;
    }
    if (again.current) {
      again.current = false;
      return syncRef.current();
    }
  }, [lockLocal]);
  useEffect(() => {
    syncRef.current = sync;
  }, [sync]);

  useEffect(() => {
    if (DEMO) return;
    queue.current = readJSON<Op[]>(QUEUE) ?? [];
    // Syncing with the server is exactly what this effect is for; state updates happen after the fetch.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void sync();
    const onFocus = () => document.visibilityState === "visible" && void sync();
    const onOnline = () => void sync();
    document.addEventListener("visibilitychange", onFocus);
    window.addEventListener("online", onOnline);
    const t = setInterval(() => document.visibilityState === "visible" && void sync(), 60_000);
    return () => {
      document.removeEventListener("visibilitychange", onFocus);
      window.removeEventListener("online", onOnline);
      clearInterval(t);
    };
  }, [sync]);

  /** Apply now, persist locally, and send in the background. */
  function dispatch(...ops: Op[]) {
    const next = ops.reduce(applyOp, latest.current);
    latest.current = next;
    setState(next);
    if (DEMO) return;
    queue.current = [...queue.current, ...ops];
    writeJSON(QUEUE, queue.current); // CACHE stays the last server copy; the queue is replayed on top at startup
    setState((s) => ({ ...s, pending: queue.current.length }));
    void sync();
  }

  const potFor = (c: Commitment) => latest.current.pots.find((p) => p.commitmentIds.includes(c.id));

  const actions: Actions = {
    async unlock(password) {
      const res = await fetch("/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      }).catch(() => null);
      if (!res) return "Can't reach the server. Check your connection.";
      if (!res.ok) return ((await res.json().catch(() => ({}))) as { error?: string }).error ?? "Couldn't unlock.";
      setState((s) => ({ ...s, status: "loading" }));
      await sync();
      return null;
    },
    lock() {
      void fetch("/api/logout", { method: "POST" }).catch(() => {});
      lockLocal();
    },
    addExpense(e) {
      const id = newId();
      dispatch({ t: "upsert", table: "expenses", doc: { ...e, id, createdAt: Date.now() } });
      return id;
    },
    deleteExpense: (id) => dispatch({ t: "delete", table: "expenses", id }),
    restoreExpense: (e) => dispatch({ t: "upsert", table: "expenses", doc: e }),
    savePlan: (plan) => dispatch({ t: "plan", plan }),
    saveMeta: (meta) => dispatch({ t: "meta", meta: { ...latest.current.meta, ...meta } }),
    saveCommitment: (c) => dispatch({ t: "upsert", table: "commitments", doc: { ...c, months: [...c.months].sort() } }),
    deleteCommitment: (id) => dispatch({ t: "delete", table: "commitments", id }),
    setPaid(c, month, paid) {
      const cur = latest.current.commitments.find((x) => x.id === c.id) ?? c;
      if (cur.paidMonths.includes(month) === paid)
        return { finished: paid && cur.months.every((m) => cur.paidMonths.includes(m)) };
      const paidMonths = paid ? [...cur.paidMonths, month].sort() : cur.paidMonths.filter((m) => m !== month);
      const ops: Op[] = [{ t: "upsert", table: "commitments", doc: { ...cur, paidMonths } }];
      // Paying from a set-aside pot uses up that pot's money; un-paying puts it back.
      const pot = potFor(cur);
      if (pot && paid && pot.saved > 0)
        ops.push({ t: "upsert", table: "pots", doc: { ...pot, saved: Math.max(0, pot.saved - cur.amount) } });
      if (pot && !paid)
        ops.push({ t: "upsert", table: "pots", doc: { ...pot, saved: Math.min(pot.target, pot.saved + cur.amount) } });
      dispatch(...ops);
      return { finished: paid && cur.months.every((m) => paidMonths.includes(m)) };
    },
    setSkipped(c, skipped) {
      if (c.mustPay && skipped) return;
      const cur = latest.current.commitments.find((x) => x.id === c.id) ?? c;
      dispatch({ t: "upsert", table: "commitments", doc: { ...cur, skipped } });
    },
    savePot: (p) => dispatch({ t: "upsert", table: "pots", doc: p }),
    deletePot: (id) => dispatch({ t: "delete", table: "pots", id }),
    adjustPot(p, delta) {
      const cur = latest.current.pots.find((x) => x.id === p.id) ?? p;
      dispatch({ t: "upsert", table: "pots", doc: { ...cur, saved: Math.max(0, cur.saved + delta) } });
    },
    addWish: (w) =>
      dispatch({ t: "upsert", table: "wishlist", doc: { ...w, id: newId(), createdAt: Date.now(), status: "waiting" } }),
    resolveWish(w, status) {
      const ops: Op[] = [{ t: "upsert", table: "wishlist", doc: { ...w, status, resolvedAt: Date.now() } }];
      if (status === "bought")
        ops.push({
          t: "upsert",
          table: "expenses",
          doc: { id: newId(), amount: w.amount, categoryId: w.categoryId, note: w.name, date: dayKey(), createdAt: Date.now() },
        });
      dispatch(...ops);
    },
  };

  return <DataCtx.Provider value={{ ...state, ...actions }}>{children}</DataCtx.Provider>;
}

export function useData() {
  const ctx = useContext(DataCtx);
  if (!ctx) throw new Error("useData outside DataProvider");
  return ctx;
}

// Month keys are "YYYY-MM", day keys are "YYYY-MM-DD" (local time).

export interface Category {
  id: string;
  name: string;
  jp: string; // decorative label
  emoji: string;
  monthly: number; // budget in a normal month
  tripMonthly?: number | null; // budget in trip months (null = same as monthly)
  isRemainder?: boolean; // "whatever's left under the cap"
  period?: "week" | "month"; // month = one monthly allowance, kept out of the weekly number
  color: string; // css color token name, e.g. "pink"
}

export interface IncomeItem {
  id: string;
  label: string;
  amount: number;
  date: string; // YYYY-MM-DD
}

export interface Plan {
  version?: number;
  periodStart: string; // YYYY-MM
  periodEnd: string; // YYYY-MM
  openingCash: number;
  openingDate: string; // YYYY-MM-DD — cash on hand as of this day
  salary: {
    gross: number;
    officeScheme: number;
    toParents: number;
    creditDay: number; // day of month my share lands
    months: string[]; // months in which my share is credited
  };
  incomes: IncomeItem[]; // one-time inflows (bonus, office payout)
  laptopFund: number; // separate, never counted as savings
  categories: Category[];
  monthlyCap: number;
  tripMonthCap: number;
  tripMonths: string[];
  savingsTargets: Record<string, number>; // month -> amount saved that month
  goal: number;
  milestones: number[];
  installmentWarn: number;
  wishlistThreshold: number;
  wishlistHours: number;
}

export interface Meta {
  lastMilestone: number;
  celebrated: string[]; // commitment ids whose finish was celebrated
}

export interface UserDoc {
  plan: Plan;
  meta: Meta;
  seededAt: number;
}

export interface Expense {
  id: string;
  amount: number;
  categoryId: string;
  note?: string;
  date: string; // YYYY-MM-DD
  createdAt: number;
}

export type PayMode = "cash" | "emi" | "paylater" | "loan" | "bill";

export interface Commitment {
  id: string;
  name: string;
  amount: number; // per payment
  months: string[]; // payment months, sorted
  kind: "one-time" | "installment";
  mode: PayMode;
  mustPay: boolean;
  optional: boolean;
  ongoing?: boolean; // no fixed end (shown as "ongoing")
  skipped: boolean;
  paidMonths: string[];
  note?: string;
  order: number;
}

export interface Pot {
  id: string;
  name: string;
  jp: string;
  target: number;
  saved: number;
  commitmentIds: string[];
  order: number;
}

export interface WishItem {
  id: string;
  name: string;
  amount: number;
  categoryId: string;
  createdAt: number;
  status: "waiting" | "bought" | "dropped";
  resolvedAt?: number;
}

const inr = new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 });

/** ₹1,00,000 style. Negative values get a real minus sign. */
export function rupees(n: number): string {
  const r = Math.round(n);
  return `${r < 0 ? "−" : ""}₹${inr.format(Math.abs(r))}`;
}

/** Digits only (Indian grouping), no symbol. */
export function digits(n: number): string {
  return inr.format(Math.abs(Math.round(n)));
}

/** Compact: ₹950, ₹16k, ₹1.95L. */
export function rupeesShort(n: number): string {
  const sign = n < 0 ? "−" : "";
  const a = Math.abs(n);
  if (a >= 100000) return `${sign}₹${trim(a / 100000)}L`;
  if (a >= 1000) return `${sign}₹${trim(a / 1000)}k`;
  return `${sign}₹${Math.round(a)}`;
}

function trim(x: number): string {
  return x.toFixed(2).replace(/\.?0+$/, "");
}

import type { Category, Commitment, Expense, Plan, WishItem } from "./types";
import { addDays, dayInMonth, daysInMonth, monthOf, monthRange, parseDay, weekOf } from "./dates";
import { rupees } from "./format";

/* ---------- budgets ---------- */

/** Categories with one monthly allowance (perfume) stay out of the weekly number. */
export const isMonthly = (c: Category) => c.period === "month";

export const isTripMonth = (plan: Plan, m: string) => plan.tripMonths.includes(m);
export const capFor = (plan: Plan, m: string) => (isTripMonth(plan, m) ? plan.tripMonthCap : plan.monthlyCap);

function fixedCategoryBudget(plan: Plan, c: Category, m: string): number {
  if (isTripMonth(plan, m) && c.tripMonthly != null) return c.tripMonthly;
  return c.monthly;
}

/** Budget per category for a month. The remainder category gets whatever is left under the cap. */
export function budgetsFor(plan: Plan, m: string): Record<string, number> {
  const out: Record<string, number> = {};
  let used = 0;
  for (const c of plan.categories) {
    if (c.isRemainder) continue;
    out[c.id] = fixedCategoryBudget(plan, c, m);
    used += out[c.id];
  }
  const rest = Math.max(0, capFor(plan, m) - used);
  for (const c of plan.categories) if (c.isRemainder) out[c.id] = rest;
  return out;
}

export const salaryShare = (plan: Plan) => plan.salary.gross - plan.salary.officeScheme - plan.salary.toParents;
export const takeHome = (plan: Plan) => plan.salary.gross - plan.salary.officeScheme;

/* ---------- money in ---------- */

export interface Inflow {
  label: string;
  amount: number;
  date: string;
}

export function inflows(plan: Plan): Inflow[] {
  const list: Inflow[] = [{ label: "Opening cash", amount: plan.openingCash, date: plan.openingDate }];
  for (const m of plan.salary.months)
    list.push({ label: "Salary (my share)", amount: salaryShare(plan), date: dayInMonth(m, plan.salary.creditDay) });
  for (const i of plan.incomes) list.push({ label: i.label, amount: i.amount, date: i.date });
  return list.sort((a, b) => a.date.localeCompare(b.date));
}

export const inflowsIn = (plan: Plan, m: string) => inflows(plan).filter((i) => monthOf(i.date) === m);
const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);

/* ---------- money out ---------- */

export function spentBetween(expenses: Expense[], from: string, to: string, categoryId?: string): number {
  let s = 0;
  for (const e of expenses)
    if (e.date >= from && e.date <= to && (!categoryId || e.categoryId === categoryId)) s += e.amount;
  return s;
}

export const spentInMonth = (expenses: Expense[], m: string, categoryId?: string) =>
  spentBetween(expenses, `${m}-01`, `${m}-31`, categoryId);

export const isPaid = (c: Commitment) => c.months.every((m) => c.paidMonths.includes(m));
export const remainingPayments = (c: Commitment) => c.months.filter((m) => !c.paidMonths.includes(m));
export const endMonth = (c: Commitment) => c.months[c.months.length - 1];

export interface Due {
  c: Commitment;
  paid: boolean;
}

/** Commitments with a payment in month `m` (skipped ones excluded). */
export function dueIn(commitments: Commitment[], m: string): Due[] {
  return commitments
    .filter((c) => !c.skipped && c.months.includes(m))
    .map((c) => ({ c, paid: c.paidMonths.includes(m) }));
}

/** EMI / paylater / loan / bill total for a month. */
export const installmentsTotal = (commitments: Commitment[], m: string) =>
  sum(dueIn(commitments, m).filter((d) => d.c.mode !== "cash").map((d) => d.c.amount));

/** Every unpaid, unskipped payment from now on, including EMIs that run past the period. */
export const upcomingCommitted = (commitments: Commitment[]) =>
  sum(commitments.filter((c) => !c.skipped).map((c) => remainingPayments(c).length * c.amount));

/* ---------- balance ---------- */

/** Savings right now: cash in since the opening date, minus logged spending and paid commitments. */
export function currentBalance(plan: Plan, expenses: Expense[], commitments: Commitment[], today: string): number {
  const inn = sum(inflows(plan).filter((i) => i.date >= plan.openingDate && i.date <= today).map((i) => i.amount));
  const out = spentBetween(expenses, plan.openingDate, today);
  const paid = sum(commitments.map((c) => c.paidMonths.length * c.amount));
  return inn - out - paid;
}

/* ---------- month view ---------- */

export interface MonthSummary {
  month: string;
  income: number;
  incomeReceived: number;
  cap: number;
  spent: number;
  due: Due[];
  dueTotal: number;
  paidTotal: number;
  savedSoFar: number; // income received − spent − paid
  projectedSaved: number; // full-month estimate
  target: number;
}

export function monthSummary(
  plan: Plan,
  expenses: Expense[],
  commitments: Commitment[],
  m: string,
  today: string,
): MonthSummary {
  const ins = inflowsIn(plan, m);
  const income = sum(ins.map((i) => i.amount));
  const incomeReceived = sum(ins.filter((i) => i.date <= today).map((i) => i.amount));
  const cap = capFor(plan, m);
  const spent = spentInMonth(expenses, m);
  const due = dueIn(commitments, m);
  const dueTotal = sum(due.map((d) => d.c.amount));
  const paidTotal = sum(due.filter((d) => d.paid).map((d) => d.c.amount));
  const cur = monthOf(today);
  const expectedSpend = m < cur ? spent : Math.max(spent, cap);
  return {
    month: m,
    income,
    incomeReceived,
    cap,
    spent,
    due,
    dueTotal,
    paidTotal,
    savedSoFar: incomeReceived - spent - paidTotal,
    projectedSaved: income - expectedSpend - dueTotal,
    target: plan.savingsTargets[m] ?? 0,
  };
}

/* ---------- projection ---------- */

export interface ProjectionRow {
  month: string;
  when: "past" | "current" | "future";
  plan: number; // end-of-month balance if everything goes to plan
  projected: number; // actuals so far + plan for the rest
  target: number; // cumulative savings targets
}

export function projection(plan: Plan, expenses: Expense[], commitments: Commitment[], today: string): ProjectionRow[] {
  const cur = monthOf(today);
  let p = 0;
  let q = 0;
  let t = 0;
  return monthRange(plan.periodStart, plan.periodEnd).map((m) => {
    const income = sum(inflowsIn(plan, m).map((i) => i.amount));
    const cap = capFor(plan, m);
    const spent = spentInMonth(expenses, m);
    const allDue = sum(commitments.filter((c) => c.months.includes(m)).map((c) => c.amount));
    const due = sum(dueIn(commitments, m).map((d) => d.c.amount));
    const spend = m < cur ? spent : m === cur ? Math.max(spent, cap) : cap;
    p += income - cap - allDue;
    q += income - spend - due;
    t += plan.savingsTargets[m] ?? 0;
    return { month: m, when: m < cur ? "past" : m === cur ? "current" : "future", plan: p, projected: q, target: t };
  });
}

/** Months from the current one to the end of the period, inclusive. */
export function monthsLeft(plan: Plan, today: string): number {
  const cur = monthOf(today);
  const start = cur < plan.periodStart ? plan.periodStart : cur;
  return start > plan.periodEnd ? 0 : monthRange(start, plan.periodEnd).length;
}

/* ---------- week ---------- */

export interface CatSpend {
  cat: Category;
  budget: number;
  spent: number;
}

export interface WeekStats {
  start: string;
  end: string;
  budget: number;
  spent: number;
  left: number;
  daysLeft: number; // including today
  perCat: CatSpend[];
}

/** Weekly allowance = (monthly cap − monthly-only categories) ÷ weeks in the month. */
export function weekStats(plan: Plan, expenses: Expense[], day: string, today: string = day): WeekStats {
  const { start, end } = weekOf(day);
  const m = monthOf(day);
  const factor = 7 / daysInMonth(m);
  const budgets = budgetsFor(plan, m);
  const weekly = plan.categories.filter((c) => !isMonthly(c));
  const monthlyOnly = sum(plan.categories.filter(isMonthly).map((c) => budgets[c.id] ?? 0));
  const budget = Math.round((capFor(plan, m) - monthlyOnly) * factor);
  const skip = new Set(plan.categories.filter(isMonthly).map((c) => c.id));
  const spent = sum(
    expenses.filter((e) => e.date >= start && e.date <= end && !skip.has(e.categoryId)).map((e) => e.amount),
  );
  const perCat = weekly.map((cat) => ({
    cat,
    budget: Math.round((budgets[cat.id] ?? 0) * factor),
    spent: spentBetween(expenses, start, end, cat.id),
  }));
  const daysLeft = today > end ? 0 : today < start ? 7 : Math.round((+parseDay(end) - +parseDay(today)) / 864e5) + 1;
  return { start, end, budget, spent, left: budget - spent, daysLeft, perCat };
}

export interface MonthlyAllowance {
  cat: Category;
  month: string;
  budget: number;
  spent: number;
  entries: Expense[];
}

/** This month's (or any month's) state for a monthly-only category like perfume. */
export function monthlyAllowance(plan: Plan, expenses: Expense[], cat: Category, m: string): MonthlyAllowance {
  const entries = expenses.filter((e) => e.categoryId === cat.id && monthOf(e.date) === m);
  return { cat, month: m, budget: budgetsFor(plan, m)[cat.id] ?? 0, spent: sum(entries.map((e) => e.amount)), entries };
}

export type Mood = "happy" | "worried" | "dramatic";

export function moodFor(w: WeekStats): Mood {
  if (w.spent > w.budget) return "dramatic";
  // Compare against how much of the week has gone by, so Monday splurges still register.
  const elapsed = Math.max(1, 7 - w.daysLeft + 1) / 7;
  const pace = w.budget > 0 ? w.spent / (w.budget * elapsed) : 0;
  return w.spent >= w.budget * 0.8 || pace > 1.15 ? "worried" : "happy";
}

/* ---------- sunday check-in ---------- */

export interface CheckIn {
  week: WeekStats;
  lastWeekSpent: number;
  biggest?: Expense;
  noSpendDays: number;
  byCat: CatSpend[];
  avoided: number;
  suggestion: string;
}

export function checkIn(plan: Plan, expenses: Expense[], wishlist: WishItem[], day: string, today: string): CheckIn {
  const week = weekStats(plan, expenses, day, today);
  const last = weekOf(addDays(week.start, -1));
  const lastWeekSpent = spentBetween(expenses, last.start, last.end);
  const inWeek = expenses.filter((e) => e.date >= week.start && e.date <= week.end);
  const biggest = [...inWeek].sort((a, b) => b.amount - a.amount)[0];
  const spendDays = new Set(inWeek.map((e) => e.date));
  const elapsed = 7 - week.daysLeft + (week.daysLeft > 0 ? 1 : 0);
  const noSpendDays = Math.max(0, elapsed - spendDays.size);
  const byCat = [...week.perCat].filter((c) => c.spent > 0 || c.budget > 0).sort((a, b) => b.spent - a.spent);
  const startMs = +parseDay(week.start);
  const endMs = +parseDay(week.end) + 864e5;
  const avoided = sum(
    wishlist
      .filter((w) => w.status === "dropped" && (w.resolvedAt ?? 0) >= startMs && (w.resolvedAt ?? 0) < endMs)
      .map((w) => w.amount),
  );

  return { week, lastWeekSpent, biggest, noSpendDays, byCat, avoided, suggestion: suggest(week, byCat, lastWeekSpent) };
}

function suggest(week: WeekStats, byCat: CatSpend[], lastWeekSpent: number): string {
  const worst = byCat
    .filter((c) => c.spent > c.budget)
    .sort((a, b) => b.spent - b.budget - (a.spent - a.budget))[0];
  if (worst) {
    const over = worst.spent - worst.budget;
    return worst.cat.isRemainder
      ? `Impulse spending ran ${rupees(over)} over. Put anything over ₹1,000 on the 48-hour wishlist next week.`
      : `${worst.cat.name} went ${rupees(over)} over. Aim for ${rupees(worst.budget)} next week, or trim it from Fun.`;
  }
  if (week.spent === 0) return "No spending logged this week. If that's not real, log from memory now while it's fresh.";
  if (week.left > 0)
    return `You came in ${rupees(week.left)} under. Move it to a set-aside pot so it doesn't drift into impulse buys.`;
  if (lastWeekSpent > 0 && week.spent > lastWeekSpent * 1.2)
    return `Spending jumped ${Math.round((week.spent / lastWeekSpent - 1) * 100)}% from last week. Plan meals before you shop.`;
  return "Right on budget. Keep logging every spend the moment it happens.";
}

import "server-only";
import { createHash, createHmac, timingSafeEqual } from "node:crypto";
import { sql, ensureSchema } from "./db";

export const COOKIE = "kb_session";
export const MAX_AGE = 60 * 60 * 24 * 180; // stay unlocked on the phone for ~6 months

function secret() {
  const s = process.env.SESSION_SECRET;
  if (!s || s.length < 32) throw new Error("SESSION_SECRET must be at least 32 characters");
  return s;
}

const sign = (exp: number) => createHmac("sha256", secret()).update(`kb1.${exp}`).digest("base64url");

export function makeToken() {
  const exp = Date.now() + MAX_AGE * 1000;
  return `${exp}.${sign(exp)}`;
}

export function validToken(token: string | undefined): boolean {
  if (!token) return false;
  const [expStr, sig] = token.split(".");
  const exp = Number(expStr);
  if (!exp || exp < Date.now() || !sig) return false;
  const want = Buffer.from(sign(exp));
  const got = Buffer.from(sig);
  return want.length === got.length && timingSafeEqual(want, got);
}

export function hasSession(req: Request): boolean {
  const raw = req.headers.get("cookie") ?? "";
  const token = raw
    .split(";")
    .map((c) => c.trim())
    .find((c) => c.startsWith(`${COOKIE}=`))
    ?.slice(COOKIE.length + 1);
  return validToken(token);
}

const digest = (s: string) => createHash("sha256").update(s).digest();

export function passwordMatches(input: string): boolean {
  const pw = process.env.APP_PASSWORD;
  if (!pw) throw new Error("APP_PASSWORD is not set");
  return timingSafeEqual(digest(input), digest(pw));
}

const WINDOW_MIN = 15;
const MAX_FAILS = 10;

/** Global limit (single-user app): 10 wrong passwords per 15 minutes, tracked in Postgres. */
export async function tooManyFailures(): Promise<boolean> {
  await ensureSchema();
  const db = sql();
  const [row] = await db`select count(*)::int as n from auth_failures where at > now() - make_interval(mins => ${WINDOW_MIN})`;
  return row.n >= MAX_FAILS;
}

export async function recordFailure() {
  const db = sql();
  await db.transaction([
    db`insert into auth_failures default values`,
    db`delete from auth_failures where at < now() - interval '1 day'`,
  ]);
}

export async function clearFailures() {
  await sql()`delete from auth_failures`;
}

import "server-only";
import { neon, type NeonQueryFunction } from "@neondatabase/serverless";
import { TABLES, type Op, type Snapshot } from "../ops";
import { migratePlan, seedCommitments, seedPlan, seedPots } from "../seed";
import type { Commitment, Expense, Meta, Plan, Pot, WishItem } from "../types";

let client: NeonQueryFunction<false, false> | null = null;
export function sql() {
  if (!process.env.DATABASE_URL) throw new Error("DATABASE_URL is not set");
  return (client ??= neon(process.env.DATABASE_URL));
}

const SCHEMA = [
  `create table if not exists app_state (
     id smallint primary key default 1 check (id = 1),
     plan jsonb not null,
     meta jsonb not null,
     seeded_at timestamptz not null default now()
   )`,
  `create table if not exists expenses (
     id text primary key,
     amount integer not null check (amount >= 0),
     category_id text not null,
     note text,
     date date not null,
     created_at bigint not null
   )`,
  `create index if not exists expenses_date_idx on expenses (date desc)`,
  `create table if not exists commitments (id text primary key, doc jsonb not null, sort integer not null default 0, updated_at timestamptz not null default now())`,
  `create table if not exists pots (id text primary key, doc jsonb not null, sort integer not null default 0, updated_at timestamptz not null default now())`,
  `create table if not exists wishlist (id text primary key, doc jsonb not null, created_at bigint not null, updated_at timestamptz not null default now())`,
  `create table if not exists auth_failures (at timestamptz not null default now())`,
];

let schemaReady: Promise<unknown> | null = null;
export function ensureSchema() {
  const db = sql();
  return (schemaReady ??= db.transaction(SCHEMA.map((q) => db.query(q))).catch((e) => {
    schemaReady = null;
    throw e;
  }));
}

/** Everything the app needs, seeding the Oct → Mar plan on the very first load. */
export async function loadAll(today: string): Promise<Snapshot> {
  await ensureSchema();
  const db = sql();
  let state = await db`select plan, meta from app_state where id = 1`;
  if (state.length === 0) {
    await seed(today);
    state = await db`select plan, meta from app_state where id = 1`;
  }
  const stored = state[0].plan as Plan;
  const plan = migratePlan(stored);
  if (plan !== stored) await db`update app_state set plan = ${JSON.stringify(plan)}::jsonb where id = 1`;
  const [expenses, commitments, pots, wishlist] = await db.transaction(
    [
      db`select id, amount, category_id, note, to_char(date, 'YYYY-MM-DD') as date, created_at::float8 as created_at
         from expenses order by date desc, created_at desc`,
      db`select doc from commitments order by sort`,
      db`select doc from pots order by sort`,
      db`select doc from wishlist order by created_at desc`,
    ],
    { readOnly: true },
  );
  return {
    plan,
    meta: { lastMilestone: 0, celebrated: [], ...(state[0].meta as Partial<Meta>) },
    expenses: expenses.map(
      (r): Expense => ({
        id: r.id,
        amount: r.amount,
        categoryId: r.category_id,
        note: r.note ?? undefined,
        date: r.date,
        createdAt: Number(r.created_at),
      }),
    ),
    commitments: commitments.map((r) => r.doc as Commitment),
    pots: pots.map((r) => r.doc as Pot),
    wishlist: wishlist.map((r) => r.doc as WishItem),
  };
}

async function seed(today: string) {
  const db = sql();
  const plan = seedPlan(today);
  await db.transaction([
    db`insert into app_state (id, plan, meta) values (1, ${JSON.stringify(plan)}::jsonb, ${JSON.stringify({ lastMilestone: 0, celebrated: [] })}::jsonb)
       on conflict (id) do nothing`,
    ...seedCommitments().map(
      (c) => db`insert into commitments (id, doc, sort) values (${c.id}, ${JSON.stringify(c)}::jsonb, ${c.order}) on conflict (id) do nothing`,
    ),
    ...seedPots().map(
      (p) => db`insert into pots (id, doc, sort) values (${p.id}, ${JSON.stringify(p)}::jsonb, ${p.order}) on conflict (id) do nothing`,
    ),
  ]);
}

/* ---------- writes ---------- */

const ID = /^[\w-]{1,80}$/;
const DAY = /^\d{4}-\d{2}-\d{2}$/;

/** Rejects anything malformed before it reaches SQL. Returns an error message or null. */
export function validate(op: unknown): string | null {
  const o = op as Op;
  if (!o || typeof o !== "object") return "op must be an object";
  if (o.t === "plan") return o.plan && typeof o.plan === "object" && Array.isArray(o.plan.categories) ? null : "bad plan";
  if (o.t === "meta") return o.meta && typeof o.meta === "object" ? null : "bad meta";
  if (o.t !== "upsert" && o.t !== "delete") return "unknown op";
  if (!TABLES.includes(o.table)) return "unknown table";
  if (o.t === "delete") return ID.test(o.id) ? null : "bad id";
  if (!o.doc || !ID.test(o.doc.id)) return "bad doc id";
  if (o.table === "expenses") {
    const e = o.doc;
    if (!Number.isInteger(e.amount) || e.amount < 0 || e.amount > 10_000_000) return "bad amount";
    if (!DAY.test(e.date) || typeof e.categoryId !== "string") return "bad expense";
  }
  return null;
}

export async function applyOps(ops: Op[]) {
  await ensureSchema();
  const db = sql();
  const queries = ops.map((op) => {
    switch (op.t) {
      case "plan":
        return db`update app_state set plan = ${JSON.stringify(op.plan)}::jsonb where id = 1`;
      case "meta":
        return db`update app_state set meta = ${JSON.stringify(op.meta)}::jsonb where id = 1`;
      case "delete":
        // Table names come from the validated whitelist, never from free text.
        return db.query(`delete from ${op.table} where id = $1`, [op.id]);
      case "upsert": {
        if (op.table === "expenses") {
          const e = op.doc;
          return db`insert into expenses (id, amount, category_id, note, date, created_at)
                    values (${e.id}, ${e.amount}, ${e.categoryId}, ${e.note ?? null}, ${e.date}, ${e.createdAt})
                    on conflict (id) do update set amount = excluded.amount, category_id = excluded.category_id,
                      note = excluded.note, date = excluded.date`;
        }
        const doc = JSON.stringify(op.doc);
        if (op.table === "wishlist")
          return db`insert into wishlist (id, doc, created_at) values (${op.doc.id}, ${doc}::jsonb, ${op.doc.createdAt})
                    on conflict (id) do update set doc = excluded.doc, updated_at = now()`;
        return db.query(
          `insert into ${op.table} (id, doc, sort) values ($1, $2::jsonb, $3)
           on conflict (id) do update set doc = excluded.doc, sort = excluded.sort, updated_at = now()`,
          [op.doc.id, doc, op.doc.order],
        );
      }
    }
  });
  if (queries.length) await db.transaction(queries);
}
